static HMODULE xl_load_system_dwrite() {
    HMODULE module = LoadLibraryExW(L"dwrite.dll", NULL, LOAD_LIBRARY_SEARCH_DEFAULT_DIRS);
    if (module || GetLastError() != ERROR_INVALID_PARAMETER) {
        return module;
    }
    WCHAR path[MAX_PATH];
    const UINT length = GetSystemDirectoryW(path, MAX_PATH);
    constexpr WCHAR suffix[] = L"\\dwrite.dll";
    if (length == 0 || length >= MAX_PATH || length + sizeof(suffix) / sizeof(WCHAR) > MAX_PATH) {
        return nullptr;
    }
    for (size_t index = 0; index < sizeof(suffix) / sizeof(WCHAR); ++index) {
        path[length + index] = suffix[index];
    }
    return LoadLibraryW(path);
}

